export const fastFormats: DefinedFormats = {
  ...fullFormats,
  date: fmtDef(/^\d\d\d\d-[-]\d-[-]\d$/, compareDate),
  time: fmtDef(
    /^(?:[-]\d:[-]\d:[-]\d|::)(?:\.\d+)?(?:z|[+-]\d\d(?::?\d\d)?)?$/i,
    compareTime
  ),
  "date-time": fmtDef(
    /^\d\d\d\d-[-]\d-[-]\d[t\s](?:[-]\d:[-]\d:[-]\d|::)(?:\.\d+)?(?:z|[+-]\d\d(?::?\d\d)?)$/i,
    compareDateTime
  ),
  // uri: https://github.com/mafintosh/is-my-json-valid/blob/master/formats.js
  uri: /^(?:[a-z][a-z-+\-.]:)(?:\/?\/)?[^\s]$/i,
  "uri-reference": /^(?:(?:[a-z][a-z-+\-.]:)?\/?\/)?(?:[^\\\s][^\s])?(?:[^\\\s])?$/i,
  // email (sources from jsen validator):
  // http://stackoverflow.com/questions//using-a-regular-expression-to-validate-an-email-addressanswer-
  // http://www.w.org/TR/html/forms.htmlvalid-e-mail-address (search for 'wilful violation')
  email:
    /^[a-z-.!$%&'+/=?^_`{|}~-]+@[a-z-](?:[a-z--]{,}[a-z-])?(?:\.[a-z-](?:[a-z--]{,}[a-z-])?)$/i,
}

